\begin{flushleft}
\footnotesize $^{\dagger}$ At $\alpha = +20$, the control flip rate exceeds steering ($p = 0.053$), indicating coherence collapse at extreme perturbation magnitudes. $^{\ddagger}$ Gemma: re-run after correcting a label assignment error in an earlier version of the data preparation pipeline.
\end{flushleft}
\end{table}

